    def __init__(self, name: str, options: ASROptions
                 # lan, modelsize=None, cache_dir=None, model_dir=None, logfile=sys.stderr
                 ):
        self.name = name
        self.options = options
        self.logger = logging.getLogger(self.__class__.__name__)
        self.transcribe_kargs = {}
        self._prepare()

    def _prepare(self):
        self.model = self.load_model()
        if self.use_diarization():
            self.diarize_model = self.load_diarize_model()


    def id(self) -> str:
        return '-'.join([self.options.model_variant, self.options.model, self.name, self.language()])

    def language(self) -> str:
        if not self.options.language:
            return "auto"
        return self.options.language

    @abstractmethod
